    [1070] = { "100110", "101001", "101001", "111001", "101001", "101001", "100110" },   -- U+042E
    [1071] = { "01111", "10001", "10001", "01111", "01001", "10001", "10001" },   -- U+042F
    [1168] = { "00001", "11111", "10000", "10000", "10000", "10000", "10000" },   -- U+0490
  },
}
for face, glyphs in pairs(EXT) do
    local F = ZeD.PixelFonts and ZeD.PixelFonts[face]
    if F then
        for cp, rows in pairs(glyphs) do
            local ch = string.char(cp)
            if F[ch] == nil then F[ch] = rows end
        end
    end
end
